CREATE TYPE "CustomerStatus" AS ENUM ('ACTIVE','INACTIVE');
CREATE TYPE "OrderStatus" AS ENUM ('PENDING','CONFIRMED','PROCESSING','DELIVERED','CANCELLED');
CREATE TYPE "PaymentStatus" AS ENUM ('PAID','PENDING','FAILED','REFUNDED');
CREATE TYPE "DeliveryStatus" AS ENUM ('NOT_SCHEDULED','SCHEDULED','PREPARING','OUT_FOR_DELIVERY','DELIVERED','DELIVERY_FAILED','RESCHEDULED','CANCELLED');
CREATE TABLE "Customer" ("id" TEXT NOT NULL,"name" TEXT NOT NULL,"email" TEXT NOT NULL,"phone" TEXT NOT NULL,"status" "CustomerStatus" NOT NULL DEFAULT 'ACTIVE',"adminNotes" TEXT,"lastLoginAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "Customer_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "Customer_email_key" ON "Customer"("email"); CREATE INDEX "Customer_status_idx" ON "Customer"("status");
CREATE TABLE "CustomerAddress" ("id" TEXT NOT NULL,"label" TEXT NOT NULL,"emirate" TEXT NOT NULL,"area" TEXT NOT NULL,"address" TEXT NOT NULL,"building" TEXT NOT NULL,"isDefault" BOOLEAN NOT NULL DEFAULT false,"customerId" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "CustomerAddress_pkey" PRIMARY KEY ("id"));
CREATE INDEX "CustomerAddress_customerId_isDefault_idx" ON "CustomerAddress"("customerId","isDefault");
CREATE TABLE "Order" ("id" TEXT NOT NULL,"orderNumber" TEXT NOT NULL,"subtotal" INTEGER NOT NULL,"deliveryFee" INTEGER NOT NULL DEFAULT 0,"total" INTEGER NOT NULL,"paymentStatus" "PaymentStatus" NOT NULL DEFAULT 'PENDING',"paymentMethod" TEXT NOT NULL,"orderStatus" "OrderStatus" NOT NULL DEFAULT 'PENDING',"deliveryStatus" "DeliveryStatus" NOT NULL DEFAULT 'NOT_SCHEDULED',"transactionReference" TEXT,"paidAt" TIMESTAMP(3),"deliveryEmirate" TEXT NOT NULL,"deliveryArea" TEXT NOT NULL,"deliveryAddress" TEXT NOT NULL,"deliveryBuilding" TEXT NOT NULL,"deliveryPhone" TEXT NOT NULL,"customerNotes" TEXT,"adminNotes" TEXT,"cancellationReason" TEXT,"cancellationNotes" TEXT,"cancelledAt" TIMESTAMP(3),"customerId" TEXT NOT NULL,"placedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "Order_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "Order_orderNumber_key" ON "Order"("orderNumber"); CREATE INDEX "Order_customerId_placedAt_idx" ON "Order"("customerId","placedAt"); CREATE INDEX "Order_orderStatus_placedAt_idx" ON "Order"("orderStatus","placedAt"); CREATE INDEX "Order_paymentStatus_idx" ON "Order"("paymentStatus");
CREATE TABLE "OrderItem" ("id" TEXT NOT NULL,"name" TEXT NOT NULL,"sku" TEXT NOT NULL,"quantity" INTEGER NOT NULL,"unitPrice" INTEGER NOT NULL,"productId" TEXT,"orderId" TEXT NOT NULL,CONSTRAINT "OrderItem_pkey" PRIMARY KEY ("id"));
CREATE INDEX "OrderItem_orderId_idx" ON "OrderItem"("orderId"); CREATE INDEX "OrderItem_productId_idx" ON "OrderItem"("productId");
ALTER TABLE "CustomerAddress" ADD CONSTRAINT "CustomerAddress_customerId_fkey" FOREIGN KEY ("customerId") REFERENCES "Customer"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "Order" ADD CONSTRAINT "Order_customerId_fkey" FOREIGN KEY ("customerId") REFERENCES "Customer"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "OrderItem" ADD CONSTRAINT "OrderItem_productId_fkey" FOREIGN KEY ("productId") REFERENCES "Product"("id") ON DELETE SET NULL ON UPDATE CASCADE;
ALTER TABLE "OrderItem" ADD CONSTRAINT "OrderItem_orderId_fkey" FOREIGN KEY ("orderId") REFERENCES "Order"("id") ON DELETE CASCADE ON UPDATE CASCADE;
